[[nodiscard]] std::span<const double> fixture_series(const char *name) {
  if (std::strcmp(name, "ar1") == 0) {
    return fx::k_ar1;
  }
  if (std::strcmp(name, "ma20") == 0) {
    return fx::k_ma20;
  }
  return fx::k_wn25;
}

// ===========================================================================
//  Acceptance: "NW t matches a statsmodels fixture to 1e-8".
// ===========================================================================
TEST(EvalHac, MeanInference_MatchesStatsmodelsFixture_To1e8) {
  double worst_t = 0.0;
  double worst_se_rel = 0.0;
  for (const fx::HacCase &c : fx::kHacCases) {
    const std::span<const double> y = fixture_series(c.series);
    const hac::Kernel kernel = c.uniform ? hac::Kernel::UniformV1 : hac::Kernel::BartlettV1;
    const hac::MeanInference mi = hac::mean_inference(y, kernel, c.lag, c.correction);
    ASSERT_EQ(mi.defined, 1U) << c.series << " lag " << c.lag;
    EXPECT_EQ(mi.fell_back, 0U) << c.series << " lag " << c.lag;
    EXPECT_EQ(mi.kernel, kernel);
    EXPECT_EQ(mi.lag, c.lag);
    EXPECT_NEAR(mi.t, c.t, 1e-8) << c.series << (c.uniform ? " uniform" : " bartlett")
                                 << " lag " << c.lag << " corr " << c.correction;
    EXPECT_NEAR(mi.se, c.se, 1e-10 * c.se) << c.series << " lag " << c.lag;
    worst_t = std::max(worst_t, std::fabs(mi.t - c.t));
    worst_se_rel = std::max(worst_se_rel, std::fabs(mi.se - c.se) / c.se);
  }
  std::printf("[EvalHac] statsmodels fixture: %zu cases, max |t - t_sm| = %.3e, "
              "max |se/se_sm - 1| = %.3e\n",
              fx::kHacCases.size(), worst_t, worst_se_rel);
}

TEST(EvalHac, LagRules_MatchStatsmodelsDefaultAndIndependentNw94) {
  for (const fx::SeriesMeta &m : fx::kSeriesMeta) {
    const std::span<const double> y = fixture_series(m.series);
    EXPECT_EQ(hac::newey_west_rule_of_thumb_lag(y.size()), m.rule_of_thumb_lag) << m.series;
    EXPECT_EQ(hac::newey_west_auto_lag(y), m.nw94_lag) << m.series;
  }
  // statsmodels' floor(4 (n/100)^(2/9)) at the panel sizes this program uses.
  EXPECT_EQ(hac::newey_west_rule_of_thumb_lag(189U), 4U);
  EXPECT_EQ(hac::newey_west_rule_of_thumb_lag(1750U), 7U);
  EXPECT_EQ(hac::newey_west_rule_of_thumb_lag(1U), 0U);
}

TEST(EvalHac, PolitisWhite_MatchesIndependentReference) {
  for (const fx::SeriesMeta &m : fx::kSeriesMeta) {
    const hac::BlockLength b = hac::politis_white(fixture_series(m.series));
    ASSERT_EQ(b.defined, 1U) << m.series;
    EXPECT_NEAR(b.circular, m.pw_circular, 1e-9 * std::max(1.0, m.pw_circular)) << m.series;
    EXPECT_NEAR(b.stationary, m.pw_stationary, 1e-9 * std::max(1.0, m.pw_stationary))
        << m.series;
  }
  // The MA(20) overlap asks for a block of about 30 at n = 500: far above the V1 block 11.
  const hac::BlockLength ma = hac::politis_white(fx::k_ma20);
  EXPECT_GT(ma.circular, 20.0);
  // Degenerate inputs are flagged, not guessed.
  const std::vector<double> flat(50U, 1.0);
  EXPECT_EQ(hac::politis_white(flat).defined, 0U);
  EXPECT_EQ(hac::politis_white(std::span<const double>{fx::k_ar1.data(), 7U}).defined, 0U);
}

// ===========================================================================
//  The versioned combine rule: IidV1 is the pre-W0 spelling term for term.
// ===========================================================================
TEST(EvalHac, TStatRuleIidV1_ReproducesPreW0FormulaBitForBit) {
  for (const fx::SeriesMeta &m : fx::kSeriesMeta) {
    const std::span<const double> y = fixture_series(m.series);
    // The pre-W0 `marginal_ic` / `column_tstats` formula, restated.
    double sum = 0.0;
    for (const double v : y) {
      sum += v;
    }
    const double mean = sum / static_cast<double>(y.size());
    double ss = 0.0;
    for (const double v : y) {
      ss += (v - mean) * (v - mean);
    }
    const double sd = std::sqrt(ss / static_cast<double>(y.size() - 1U));
    const double old_t = mean / (sd / std::sqrt(static_cast<double>(y.size())));
    const hac::MeanInference mi = hac::mean_tstat(y, hac::TStatRule::IidV1);
    ASSERT_EQ(mi.defined, 1U);
    EXPECT_EQ(mi.t, old_t) << m.series; // exact
    // Newey-West at lag 0 with the n/(n-1) correction IS the IID t.
    const hac::MeanInference nw0 = hac::mean_inference(y, hac::Kernel::BartlettV1, 0U, true);
    EXPECT_NEAR(nw0.t, old_t, 1e-12 * std::fabs(old_t)) << m.series;
  }
  EXPECT_EQ(hac::kDefaultTStatRule, hac::TStatRule::NeweyWestAutoV2);
  // Undefined cases: n < 2, zero variance, Unknown rule.
  // 0.5 is exact in binary, so the flat series has an exactly zero deviation.
  const std::vector<double> one{0.5};
  const std::vector<double> flat(10U, 0.5);
  EXPECT_EQ(hac::mean_tstat(one, hac::TStatRule::IidV1).defined, 0U);
  EXPECT_EQ(hac::mean_tstat(flat, hac::TStatRule::IidV1).defined, 0U);
  EXPECT_EQ(hac::mean_tstat(flat, hac::TStatRule::NeweyWestAutoV2).defined, 0U);
  EXPECT_EQ(hac::mean_tstat(fx::k_ar1, hac::TStatRule::Unknown).defined, 0U);
}

TEST(EvalHac, NeweyWestAuto_DeflatesTheMa20TStatByRoughlySqrtH) {
  const hac::MeanInference iid = hac::mean_tstat(fx::k_ma20, hac::TStatRule::IidV1);
  const hac::MeanInference nw = hac::mean_tstat(fx::k_ma20, hac::TStatRule::NeweyWestAutoV2);
  ASSERT_EQ(iid.defined, 1U);
  ASSERT_EQ(nw.defined, 1U);
  const double ratio = iid.t / nw.t;
  std::printf("[EvalHac] MA(20) n=500: iid t=%.4f, NW-auto t=%.4f (lag %zu), ratio %.3f "
              "(sqrt(21)=%.3f)\n",
              iid.t, nw.t, nw.lag, ratio, std::sqrt(21.0));
  EXPECT_GT(ratio, 2.5);
  EXPECT_LT(ratio, 6.0);
}

TEST(EvalHac, UniformNonPositiveVariance_FallsBackToBartlett) {
  // A strictly alternating series: the uniform lag-1 sum is n - 2(n - 1) < 0.
  std::vector<double> alt(40U);
  for (std::size_t i = 0U; i < alt.size(); ++i) {
    alt[i] = ((i % 2U) == 0U ? 1.0 : -1.0) + 0.001 * static_cast<double>(i % 3U);
  }
  const hac::MeanInference u = hac::mean_inference(alt, hac::Kernel::UniformV1, 1U, false);
  EXPECT_EQ(u.fell_back, 1U);
  EXPECT_EQ(u.kernel, hac::Kernel::BartlettV1);
  EXPECT_EQ(u.defined, 1U);
  const hac::MeanInference b = hac::mean_inference(alt, hac::Kernel::BartlettV1, 1U, false);
  EXPECT_EQ(u.se, b.se);
}

TEST(EvalHac, EwmaVarianceInflation_IidV1IsOneAndEqualWeightsMatchNeweyWest) {
  const std::span<const double> y = fx::k_ma20;
  const std::vector<double> w(y.size(), 1.0);
  const double mean = hac::detail::mean_of(y);
  EXPECT_EQ(hac::ewma_variance_inflation(y, w, mean, hac::TStatRule::IidV1), 1.0);
  const double vif = hac::ewma_variance_inflation(y, w, mean, hac::TStatRule::NeweyWestAutoV2);
  // With unit weights VIF = S_Bartlett(L) / sum e^2 at the NW-1994 lag.
  const std::size_t lag = hac::newey_west_auto_lag(y);
  const double s = hac::long_run_sum(y, mean, hac::Kernel::BartlettV1, lag);
  const double s0 = hac::long_run_sum(y, mean, hac::Kernel::BartlettV1, 0U);
  EXPECT_NEAR(vif, s / s0, 1e-12 * (s / s0));
  EXPECT_GT(vif, 4.0); // the MA(20) overlap inflates the variance several-fold
  // Mismatched spans carry no information to correct with.
  EXPECT_EQ(hac::ewma_variance_inflation(y, std::span<const double>{w.data(), 3U}, mean,
                                         hac::TStatRule::NeweyWestAutoV2),
            1.0);
}

// ===========================================================================
//  E-02: the block-length rules.
// ===========================================================================
TEST(EvalHac, BlockLenRules_V1FrozenAndV2AtLeastTwoHorizons) {
  const std::size_t horizons[] = {1U, 5U, 10U, 21U, 63U};
  const std::size_t v1[] = {5U, 5U, 5U, 11U, 32U};
  const std::size_t v2[] = {5U, 10U, 20U, 42U, 126U};
  for (std::size_t k = 0U; k < 5U; ++k) {
    EXPECT_EQ(detail::block_len_for_rule(BlockLenRule::HalfHorizonV1, horizons[k], 5U), v1[k]);
    EXPECT_EQ(detail::block_len(horizons[k], 5U), v1[k]);
    EXPECT_EQ(detail::block_len_for_rule(BlockLenRule::TwoHorizonV2, horizons[k], 5U), v2[k]);
    EXPECT_EQ(detail::block_len_for_rule(BlockLenRule::PolitisWhiteV2, horizons[k], 5U), v2[k]);
    EXPECT_GE(v2[k], 2U * horizons[k]);
  }
  EXPECT_EQ(detail::block_len_for_rule(BlockLenRule::Unknown, 21U, 5U), 0U);
  const CrossSectionIcConfig defaults{};
  EXPECT_EQ(defaults.block_len_rule, BlockLenRule::TwoHorizonV2);
  EXPECT_EQ(defaults.hac_rule, IcHacRule::HansenHodrickV1);
}

// ---------------------------------------------------------------------------
//  A small panel for the wiring tests: per-date signal-return coupling c_t follows an
//  AR(1) with coefficient `phi`, so the IC series has a controllable persistence.
// ---------------------------------------------------------------------------
struct Panel {
  std::size_t dates{};
  std::size_t instruments{};
  std::vector<double> signal, price, raw_price, terminal_value;
  std::vector<atx::u8> mask, terminal, terminal_evidenced, excluded_audited;
  std::vector<atx::i64> session_keys;

  [[nodiscard]] CrossSectionIcInput view() const {
    CrossSectionIcInput in{};
    in.dates = dates;
    in.instruments = instruments;
    in.signal = signal;
    in.price = price;
    in.raw_price = raw_price;
    in.mask = mask;
    in.terminal = terminal;
    in.terminal_evidenced = terminal_evidenced;
    in.terminal_value = terminal_value;
    in.excluded_audited = excluded_audited;
    in.session_keys = session_keys;
    return in;
  }
};

[[nodiscard]] Panel coupled_panel(std::size_t dates, std::size_t instruments, double phi,
                                  atx::u64 seed) {
  Panel p{};
  p.dates = dates;
  p.instruments = instruments;
  const std::size_t cells = dates * instruments;
  p.signal.assign(cells, 0.0);
  p.price.assign(cells, 0.0);
  p.raw_price.assign(cells, 0.0);
  p.terminal_value.assign(cells, 0.0);
  p.mask.assign(cells, atx::u8{1});
  p.terminal.assign(cells, atx::u8{0});
  p.terminal_evidenced.assign(cells, atx::u8{0});
  p.excluded_audited.assign(cells, atx::u8{0});
  p.session_keys.resize(dates);
  atx::core::Xoshiro256pp rng{seed};
  std::vector<double> level(instruments, 100.0);
  std::vector<double> prev_signal(instruments, 0.0);
  double c = 0.0;
  for (std::size_t t = 0U; t < dates; ++t) {
    p.session_keys[t] = 1'357'084'800'000'000'000 + kNanosPerDay * static_cast<atx::i64>(t);
    c = phi * c + std::sqrt(1.0 - phi * phi) * rng.normal();
    for (std::size_t i = 0U; i < instruments; ++i) {
      // The return realized INTO row t is driven by the signal of row t - 1.
      const double ret = 0.01 * (0.3 * c * prev_signal[i] + rng.normal());
      level[i] *= 1.0 + ret;
      const std::size_t cell = t * instruments + i;
      p.price[cell] = level[i];
      p.raw_price[cell] = level[i];
      prev_signal[i] = rng.normal();
      p.signal[cell] = prev_signal[i];
    }
  }
  return p;
}

[[nodiscard]] CrossSectionIcConfig base_config(std::span<const std::size_t> horizons) {
  CrossSectionIcConfig cfg{};
  cfg.horizons = horizons;
  cfg.quantiles = 5U;
  cfg.bootstrap_draws = 64U;
  cfg.bootstrap_seed = 7U;
  cfg.forward_variant = ForwardReturnVariant::DropMissingForward;
  cfg.ties = IcTieHandling::AverageRanksV1;
  return cfg;
}

[[nodiscard]] CrossSectionIcResult run(const Panel &p, const CrossSectionIcConfig &cfg) {
  auto scratch = plan_cross_section_ic(p.view(), cfg);
  if (!scratch.has_value()) {
    ADD_FAILURE() << "plan: " << scratch.error().message();
    return CrossSectionIcResult{};
  }
  auto res = compute_cross_section_ic(p.view(), cfg, *scratch);
  if (!res.has_value()) {
    ADD_FAILURE() << "compute: " << res.error().message();
    return CrossSectionIcResult{};
  }
  return std::move(*res);
}

[[nodiscard]] std::vector<double> emitted_ic(const IcHorizonSummary &h, bool rank) {
  std::vector<double> out;
  for (const IcDatePoint &p : h.series) {
    if (p.emitted != 0U) {
      out.push_back(rank ? p.rank_ic : p.pearson_ic);
    }
  }
  return out;
}

TEST(EvalHac, CrossSectionIc_HacFieldsAreHacOfTheEmittedIcSeries) {
  const Panel p = coupled_panel(400U, 30U, 0.5, 11U);
  const std::vector<std::size_t> h{1U, 5U, 21U};
  for (const IcHacRule rule : {IcHacRule::HansenHodrickV1, IcHacRule::NeweyWestV1}) {
    CrossSectionIcConfig cfg = base_config(h);
    cfg.hac_rule = rule;
    const CrossSectionIcResult r = run(p, cfg);
    ASSERT_EQ(r.horizons.size(), 3U);
    for (const IcHorizonSummary &hs : r.horizons) {
      for (const bool rank : {false, true}) {
        const std::vector<double> s = emitted_ic(hs, rank);
        const HacInterval &got = rank ? hs.full.rank_ic_mean_hac : hs.full.ic_mean_hac;
        const std::size_t overlap = hs.horizon - 1U;
        hac::Kernel kernel = hac::Kernel::UniformV1;
        std::size_t lag = std::max(overlap, hac::newey_west_rule_of_thumb_lag(s.size()));
        if (rule == IcHacRule::NeweyWestV1) {
          kernel = hac::Kernel::BartlettV1;
          lag = std::max(overlap, hac::newey_west_auto_lag(s));
        }
        const hac::MeanInference want = hac::mean_inference(s, kernel, lag, false);
        ASSERT_EQ(got.reportable, 1U) << "h=" << hs.horizon;
        EXPECT_EQ(got.n, s.size());
        EXPECT_EQ(got.lag, lag);
        EXPECT_EQ(got.t, want.t); // exact: the same routine on the same series
        EXPECT_EQ(got.se, want.se);
        EXPECT_EQ(got.lo, want.mean - kHacZ975 * want.se);
        EXPECT_EQ(got.hi, want.mean + kHacZ975 * want.se);
        EXPECT_GE(got.lag, overlap);
      }
    }
  }
}

TEST(EvalHac, CrossSectionIc_HacUnreportableCodes) {
  // 40 dates at h = 21 leaves 18 emitted dates: code 1 (n < 20).
  const Panel short_panel = coupled_panel(40U, 12U, 0.0, 3U);
  const std::vector<std::size_t> h21{21U};
  CrossSectionIcConfig cfg = base_config(h21);
  cfg.bootstrap_draws = 0U; // nothing is reportable anyway
  const CrossSectionIcResult r = run(short_panel, cfg);
  ASSERT_EQ(r.horizons.size(), 1U);
  EXPECT_EQ(r.horizons[0].full.ic_mean_hac.reportable, 0U);
  EXPECT_EQ(r.horizons[0].full.ic_mean_hac.unreportable_reason, 1U);
  EXPECT_EQ(r.horizons[0].full.ic_mean_hac.t, 0.0);
  // 150 dates at h = 21: n = 128 but n / (lag + 1) = 128 / 21 = 6 < 10: code 3.
  const Panel mid = coupled_panel(150U, 12U, 0.0, 4U);
  const CrossSectionIcResult r2 = run(mid, base_config(h21));
  ASSERT_EQ(r2.horizons.size(), 1U);
  EXPECT_EQ(r2.horizons[0].full.ic_mean_hac.unreportable_reason, 3U);
  // The common block with a prefix gap is void (code 2), exactly like its means.
  CrossSectionIcConfig gap_cfg = base_config(h21);
  gap_cfg.common_sample_dates = 150U - 21U; // past the evaluable range at delay 1 -> gap
  const CrossSectionIcResult r3 = run(mid, gap_cfg);
  ASSERT_EQ(r3.horizons.size(), 1U);
  EXPECT_GT(r3.horizons[0].common.common_prefix_gaps, 0U);
  EXPECT_EQ(r3.horizons[0].common.ic_mean_hac.unreportable_reason, 2U);
  EXPECT_EQ(r3.horizons[0].common.ic_mean_hac.point, 0.0);
}

TEST(EvalHac, PolitisWhiteV2_RaisesTheBlockOnAPersistentIcSeries) {
  // phi = 0.97: the IC series is strongly persistent, so the automatic block length is
  // far above 2h = 2 at h = 1.
  const Panel p = coupled_panel(600U, 20U, 0.97, 21U);
  const std::vector<std::size_t> h{1U};
  CrossSectionIcConfig cfg = base_config(h);
  cfg.execution_delay = 0U; // the panel's coupling acts on the next-row return
  cfg.block_len_rule = BlockLenRule::PolitisWhiteV2;
  const CrossSectionIcResult r = run(p, cfg);
  ASSERT_EQ(r.horizons.size(), 1U);
  const std::vector<double> s = emitted_ic(r.horizons[0], false);
  const hac::BlockLength pw = hac::politis_white(s);
  ASSERT_EQ(pw.defined, 1U);
  const auto want = static_cast<std::size_t>(std::ceil(pw.circular));
  std::printf("[EvalHac] PolitisWhiteV2 on a phi=0.97 IC series: b_CB=%.3f -> L=%zu "
              "(TwoHorizonV2 gives %zu)\n",
              pw.circular, r.horizons[0].block_len,
              detail::block_len_for_rule(BlockLenRule::TwoHorizonV2, 1U, 5U));
  EXPECT_EQ(r.horizons[0].block_len, std::max<std::size_t>(want, 5U));
  EXPECT_GT(r.horizons[0].block_len, 5U);
  EXPECT_EQ(r.horizons[0].full.ic_mean_ci.block_len, r.horizons[0].block_len);
  EXPECT_EQ(r.horizons[0].block_len_rule, BlockLenRule::PolitisWhiteV2);
  // Under TwoHorizonV2 the same panel keeps max(floor, 2h) = 5.
  cfg.block_len_rule = BlockLenRule::TwoHorizonV2;
  const CrossSectionIcResult r_v2 = run(p, cfg);
  ASSERT_EQ(r_v2.horizons.size(), 1U);
  EXPECT_EQ(r_v2.horizons[0].block_len, 5U);
}

TEST(EvalHac, Validation_UnknownOrOutOfRangeRulesReject) {
  const Panel p = coupled_panel(60U, 6U, 0.0, 5U);
  const std::vector<std::size_t> h{1U};
  const auto code = [&p](const CrossSectionIcConfig &cfg) {
    auto planned = plan_cross_section_ic(p.view(), cfg);
    return planned.has_value() ? atx::core::ErrorCode::Unknown : planned.error().code();
  };
  CrossSectionIcConfig cfg = base_config(h);
  EXPECT_EQ(code(cfg), atx::core::ErrorCode::Unknown); // baseline passes
  cfg.block_len_rule = BlockLenRule::Unknown;
  EXPECT_EQ(code(cfg), atx::core::ErrorCode::InvalidArgument);
  cfg = base_config(h);
  cfg.block_len_rule = static_cast<BlockLenRule>(9U);
  EXPECT_EQ(code(cfg), atx::core::ErrorCode::InvalidArgument);
  cfg = base_config(h);
  cfg.hac_rule = IcHacRule::Unknown;
  EXPECT_EQ(code(cfg), atx::core::ErrorCode::InvalidArgument);
  cfg = base_config(h);
  cfg.hac_rule = static_cast<IcHacRule>(200U);
  EXPECT_EQ(code(cfg), atx::core::ErrorCode::InvalidArgument);
}

